   */
  @JvmOverloads
  fun getProfileAndToken(
    code: String? = null,
    subjectToken: String? = null,
    subjectTokenType: String? = null,
    organizationId: String? = null,
    requestOptions: RequestOptions? = null
  ): SSOTokenResponse {
    val params = mutableListOf<Pair<String, String>>()
    params.addIfNotNull("code", code)
    val body =
      bodyOf(
        "code" to code,
        "subject_token" to subjectToken,
        "subject_token_type" to subjectTokenType,
        "organization_id" to organizationId,
        "grant_type" to "authorization_code",
        "client_id" to workos.clientId,
        "client_secret" to workos.apiKey
      )
    val config =
      RequestConfig(
        method = "POST",
        path = "/sso/token",
        queryParams = params,
        body = body,
        requestOptions = requestOptions
      )
    return workos.baseClient.request(config, SSOTokenResponse::class.java)
  }

